-- Apply to a NEW database using the owner connection. Runtime must be a separate non-owner role.
CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS session (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("providerId","accountId"));
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz DEFAULT now(), "updatedAt" timestamptz DEFAULT now());
CREATE TABLE families (id uuid PRIMARY KEY, name text NOT NULL, suspended boolean NOT NULL DEFAULT false, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE learners (id uuid PRIMARY KEY, family_id uuid NOT NULL REFERENCES families(id), name text NOT NULL, monthly_cap bigint NOT NULL DEFAULT 10000000 CHECK(monthly_cap>=0), UNIQUE(id,family_id));
CREATE TABLE memberships (user_id text NOT NULL REFERENCES "user"(id), family_id uuid NOT NULL REFERENCES families(id), role text NOT NULL CHECK(role IN ('parent','student')), learner_id uuid, active boolean NOT NULL DEFAULT true, PRIMARY KEY(user_id,family_id), FOREIGN KEY(learner_id,family_id) REFERENCES learners(id,family_id), CHECK(role<>'student' OR learner_id IS NOT NULL));
CREATE TABLE parent_links (user_id text NOT NULL, family_id uuid NOT NULL, learner_id uuid NOT NULL, PRIMARY KEY(user_id,family_id,learner_id), FOREIGN KEY(user_id,family_id) REFERENCES memberships(user_id,family_id), FOREIGN KEY(learner_id,family_id) REFERENCES learners(id,family_id));
CREATE TABLE invitations (id uuid PRIMARY KEY, token_hash text NOT NULL UNIQUE, email text NOT NULL, family_id uuid NOT NULL REFERENCES families(id), role text NOT NULL CHECK(role IN ('parent','student')), learner_id uuid, expires_at timestamptz NOT NULL, revoked_at timestamptz, accepted_at timestamptz, accepted_by text REFERENCES "user"(id), created_by text NOT NULL REFERENCES "user"(id), FOREIGN KEY(learner_id,family_id) REFERENCES learners(id,family_id));
CREATE INDEX invitations_email ON invitations(lower(email));
CREATE TABLE enrolments (id uuid PRIMARY KEY, family_id uuid NOT NULL, learner_id uuid NOT NULL, data jsonb NOT NULL, FOREIGN KEY(learner_id,family_id) REFERENCES learners(id,family_id));
CREATE UNIQUE INDEX enrolment_subject ON enrolments(learner_id,(data->>'subject'));
CREATE TABLE source_documents (id uuid PRIMARY KEY, fingerprint text NOT NULL UNIQUE, filename text NOT NULL, blob_path text, metadata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE catalogue (id uuid PRIMARY KEY, identity text NOT NULL, version integer NOT NULL, status text NOT NULL CHECK(status IN ('staged','needs_review','approved','published')), data jsonb NOT NULL, issues jsonb NOT NULL DEFAULT '[]', approved_by text REFERENCES "user"(id), approved_at timestamptz, published_at timestamptz, UNIQUE(identity,version));
CREATE TABLE catalogue_releases (family_id uuid NOT NULL REFERENCES families(id), paper_id uuid NOT NULL REFERENCES catalogue(id), released_by text NOT NULL REFERENCES "user"(id), PRIMARY KEY(family_id,paper_id));
CREATE TABLE rate_cards (id uuid PRIMARY KEY, data jsonb NOT NULL, active boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE course_evaluations (id uuid PRIMARY KEY, specification text NOT NULL, configuration_hash text NOT NULL, passed boolean NOT NULL, evidence jsonb NOT NULL, approved_by text NOT NULL REFERENCES "user"(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attempts (id uuid PRIMARY KEY, family_id uuid NOT NULL, learner_id uuid NOT NULL, mode text NOT NULL CHECK(mode IN ('guided','independent','timed','mock')), state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','in_progress','submitted','abandoned')), data jsonb NOT NULL, editor_token text, editor_epoch integer NOT NULL DEFAULT 0, started_at timestamptz, deadline timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(learner_id,family_id) REFERENCES learners(id,family_id), UNIQUE(id,family_id));
CREATE TABLE answers (attempt_id uuid NOT NULL, family_id uuid NOT NULL, question_id text NOT NULL, text text NOT NULL DEFAULT '', revision integer NOT NULL DEFAULT 0, flagged boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(attempt_id,question_id), FOREIGN KEY(attempt_id,family_id) REFERENCES attempts(id,family_id));
CREATE TABLE quotes (id uuid PRIMARY KEY, family_id uuid NOT NULL, learner_id uuid NOT NULL, attempt_id uuid NOT NULL, max_charge bigint NOT NULL CHECK(max_charge>=0), rate_card_id uuid NOT NULL REFERENCES rate_cards(id), configuration jsonb NOT NULL, expires_at timestamptz NOT NULL, accepted_at timestamptz, FOREIGN KEY(attempt_id,family_id) REFERENCES attempts(id,family_id), FOREIGN KEY(learner_id,family_id) REFERENCES learners(id,family_id));
CREATE TABLE submissions (id uuid PRIMARY KEY, family_id uuid NOT NULL, learner_id uuid NOT NULL, attempt_id uuid NOT NULL, part_key text NOT NULL DEFAULT 'all', answers jsonb NOT NULL, choices jsonb NOT NULL, ended_by text NOT NULL CHECK(ended_by IN ('manual','deadline')), submitted_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(attempt_id,family_id) REFERENCES attempts(id,family_id), FOREIGN KEY(learner_id,family_id) REFERENCES learners(id,family_id), UNIQUE(attempt_id,part_key), UNIQUE(id,family_id));
CREATE TABLE assessments (id uuid PRIMARY KEY, family_id uuid NOT NULL, learner_id uuid NOT NULL, submission_id uuid NOT NULL UNIQUE, state text NOT NULL CHECK(state IN ('awaiting_funds','queued','marking','validating','needs_review','published','failed','cancelled')), candidates jsonb NOT NULL DEFAULT '[]', effective jsonb, provenance jsonb NOT NULL DEFAULT '{}', error_code text, published_at timestamptz, FOREIGN KEY(submission_id,family_id) REFERENCES submissions(id,family_id), FOREIGN KEY(learner_id,family_id) REFERENCES learners(id,family_id));
CREATE TABLE review_decisions (id uuid PRIMARY KEY, family_id uuid NOT NULL REFERENCES families(id), assessment_id uuid NOT NULL REFERENCES assessments(id), actor_id text NOT NULL REFERENCES "user"(id), data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE exposure (family_id uuid NOT NULL REFERENCES families(id), learner_id uuid NOT NULL REFERENCES learners(id), question_id text NOT NULL, first_seen timestamptz NOT NULL DEFAULT now(), reason text NOT NULL, PRIMARY KEY(learner_id,question_id));
CREATE TABLE recovered_work (id uuid PRIMARY KEY, family_id uuid NOT NULL REFERENCES families(id), learner_id uuid NOT NULL REFERENCES learners(id), attempt_id uuid NOT NULL REFERENCES attempts(id), text jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE funding_accounts (family_id uuid PRIMARY KEY REFERENCES families(id), balance bigint NOT NULL DEFAULT 0);
CREATE TABLE reservations (id uuid PRIMARY KEY, family_id uuid NOT NULL REFERENCES families(id), learner_id uuid NOT NULL REFERENCES learners(id), quote_id uuid NOT NULL UNIQUE REFERENCES quotes(id), amount bigint NOT NULL CHECK(amount>=0), month text NOT NULL, settled bigint CHECK(settled>=0 AND settled<=amount), released_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ledger (id uuid PRIMARY KEY, family_id uuid NOT NULL REFERENCES families(id), learner_id uuid REFERENCES learners(id), amount bigint NOT NULL, kind text NOT NULL, idempotency_key text NOT NULL UNIQUE, reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments (id uuid PRIMARY KEY, family_id uuid NOT NULL REFERENCES families(id), checkout_id text UNIQUE, intent_id text UNIQUE, expected_cents integer NOT NULL CHECK(expected_cents IN(1000,2500)), credited_cents integer NOT NULL DEFAULT 0, reversed_cents integer NOT NULL DEFAULT 0, refunded_cents integer NOT NULL DEFAULT 0, disputed_cents integer NOT NULL DEFAULT 0, dispute_id text, status text NOT NULL DEFAULT 'pending');
CREATE TABLE usage_events (id uuid PRIMARY KEY, family_id uuid REFERENCES families(id), assessment_id uuid REFERENCES assessments(id), idempotency_key text NOT NULL UNIQUE, provider_cost bigint NOT NULL DEFAULT 0, user_charge bigint NOT NULL DEFAULT 0, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE operator_budget (id integer PRIMARY KEY CHECK(id=1), reserved bigint NOT NULL DEFAULT 0, spent bigint NOT NULL DEFAULT 0);
INSERT INTO operator_budget(id) VALUES(1);
CREATE TABLE study_sessions (id uuid PRIMARY KEY, family_id uuid NOT NULL, learner_id uuid NOT NULL, data jsonb NOT NULL, state text NOT NULL DEFAULT 'proposed' CHECK(state IN ('proposed','approved','completed','cancelled')), calendar_event_id text, FOREIGN KEY(learner_id,family_id) REFERENCES learners(id,family_id));
CREATE TABLE corrective_tasks (id uuid PRIMARY KEY, family_id uuid NOT NULL, learner_id uuid NOT NULL, assessment_id uuid NOT NULL REFERENCES assessments(id), topic text NOT NULL, due_at timestamptz NOT NULL, interval_days integer NOT NULL, completed_at timestamptz, FOREIGN KEY(learner_id,family_id) REFERENCES learners(id,family_id), UNIQUE(assessment_id,topic,interval_days));
CREATE TABLE calendar_connections (user_id text PRIMARY KEY REFERENCES "user"(id), encrypted_token text NOT NULL, calendar_id text NOT NULL, state text NOT NULL DEFAULT 'connected');
CREATE TABLE outbox (id uuid PRIMARY KEY, family_id uuid REFERENCES families(id), kind text NOT NULL, key text NOT NULL UNIQUE, data jsonb NOT NULL, state text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, locked_at timestamptz, available_at timestamptz NOT NULL DEFAULT now(), last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY, family_id uuid REFERENCES families(id), actor_id text NOT NULL, action text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE operational_checks (key text PRIMARY KEY, data jsonb NOT NULL, checked_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF current_setting('app.privacy_purge',true)='true' AND current_user=(SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid=TG_RELID) THEN
   IF TG_OP='DELETE' THEN RETURN OLD; END IF;
   IF TG_TABLE_NAME='ledger' AND to_jsonb(NEW)-'learner_id'=to_jsonb(OLD)-'learner_id' AND NEW.learner_id IS NULL THEN RETURN NEW; END IF;
 END IF;
 RAISE EXCEPTION 'Immutable record'; END $$;
CREATE TRIGGER immutable_submissions BEFORE UPDATE OR DELETE ON submissions FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER immutable_ledger BEFORE UPDATE OR DELETE ON ledger FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER immutable_decisions BEFORE UPDATE OR DELETE ON review_decisions FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE FUNCTION protect_published_catalogue() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='published' THEN RAISE EXCEPTION 'Published catalogue versions are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_catalogue BEFORE UPDATE OR DELETE ON catalogue FOR EACH ROW EXECUTE FUNCTION protect_published_catalogue();
-- Scoped domain queries run inside a transaction; settings are local and cannot leak through pooling.
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['learners','parent_links','enrolments','catalogue_releases','attempts','answers','quotes','submissions','assessments','review_decisions','exposure','recovered_work','funding_accounts','reservations','ledger','payments','study_sessions','corrective_tasks'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY family_isolation ON %I USING (family_id::text = current_setting(''app.family_id'',true)) WITH CHECK (family_id::text = current_setting(''app.family_id'',true))',t);
END LOOP; END $$;
CREATE INDEX attempts_deadline ON attempts(deadline) WHERE state='in_progress';
CREATE INDEX outbox_pending ON outbox(available_at) WHERE state='queued';
CREATE INDEX history_assessments ON assessments(learner_id,published_at) WHERE state='published';
